def check_status_manifest(service_name, status_file_path):
    """Check status.yaml for deployment status."""
    with open(status_file_path, 'r') as f:
        content = f.read()

    # Check for pending_deployments section with this service
    if "pending_deployments:" in content:
        pending_match = re.search(rf'- name: ({service_name})', content)
        if pending_match:
            return {"status": "pending", "details": "Service found in pending_deployments section"}

    # Check for not_deployed entries (if no pending_deployments)
    if "  - name: " in content:
        entries = re.findall(r'  - name: ([\w-]+)', content)
        if service_name in entries:
            return {"status": "pending", "details": f"Service listed as pending in status manifest"}

    # Check running services
    running_match = re.search(rf'- name: ({service_name})', content)
    if running_match:
        status_match = re.search(rf'\n  status: (\w+)', content)
        if status_match:
            status = status_match.group(1)
            return {"status": status, "details": f"Service {status}"}

    return {"status": "absent", "details": "Service not found in status manifest"}

def check_systemd(service_name, services_dir):
    """Check systemd unit files."""
    if not services_dir.exists():
        return {"status": "absent", "details": "Services directory not found"}

    service_file = services_dir / f"{service_name}.service"

    if service_file.exists():
        return {"status": "active", "details": "Systemd unit file exists"}
    else:
        return {"status": "absent", "details": "No systemd unit file found"}

def check_cron_jobs(service_name, crontab_file_path):
    """Check crontab.txt for cron job definition."""
    with open(crontab_file_path, 'r') as f:
        content = f.read()

    # Check for active cron jobs (not commented)
    if f'  {service_name} ' in content and '# ' not in content.split(f'docker exec {service_name}')[0]:
        return {"status": "active", "details": "Cron job is active and scheduled"}

    # Check for commented-out cron jobs
    if f'# {service_name}' in content or f'#  {service_name}' in content:
        return {"status": "commented-out", "details": "Cron job definition exists but is commented out in crontab.txt"}

    return {"status": "absent", "details": "No cron job entry found"}

def check_project_code(project_name, project_dir):
    """Check if project code exists and appears buildable."""
    if not project_dir.exists():
        return {"status": "absent", "details": "Project directory not found"}

    existing_files = 0
    required_files = ["Dockerfile", "requirements.txt", "src"]

    for req in required_files:
        if req == "src":
            src_dir = project_dir / "src"
            if src_dir.exists():
                existing_files += 1
        else:
            fpath = project_dir / req
            if fpath.exists():
                existing_files += 1

    return {
        "status": "code_exists",
        "details": f"Project code exists and appears buildable ({existing_files}/3 components found)",
        "existing_files": existing_files
    }

